import{_ as s,a0 as a,w as b,s as d,ao as r,I as p,a1 as u,A as n,x as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"Ubuntu每日小技巧-Ubuntu One關閉後如何切換到Dropbox或Box雲服務 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu每日小技巧-Ubuntu One關閉後如何切換到Dropbox或Box雲服務 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu每日小技巧-Ubuntu One關閉後如何切換到Dropbox或Box雲服務 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu每日小技巧-Ubuntu One關閉後如何切換到Dropbox或Box雲服務 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/Daily Ubuntu Tips--Ubuntu One Shuts Down, Switch To Dropbox Or Box Cloud Services","title":"Ubuntu每日小技巧-Ubuntu One關閉後如何切換到Dropbox或Box雲服務","tag":"201405","desc":""},"relativePath":"201405/Daily Ubuntu Tips--Ubuntu One Shuts Down, Switch To Dropbox Or Box Cloud Services.md","filePath":"[post].md"}'),i={name:"201405/Daily Ubuntu Tips--Ubuntu One Shuts Down, Switch To Dropbox Or Box Cloud Services.md"};function l(x,t,T,f,w,D){const e=a("Link");return b(),d("div",null,[t[12]||(t[12]=r('<h1 id="ubuntu每日小技巧-ubuntu-one關閉後如何切換到dropbox或box雲服務" tabindex="-1">Ubuntu每日小技巧-Ubuntu One關閉後如何切換到Dropbox或Box雲服務 <a class="header-anchor" href="#ubuntu每日小技巧-ubuntu-one關閉後如何切換到dropbox或box雲服務" aria-label="Permalink to “Ubuntu每日小技巧-Ubuntu One關閉後如何切換到Dropbox或Box雲服務”">​</a></h1><p>Canonical公司決定關閉Ubuntu One的雲服務，你可能正在尋找備份你主機的其他服務器，儘管現在有很多雲服務的提供商，但是大服務商中僅有小部分支持包括Ubuntu在內的linux。</p><p>Dropbox全面支持Ubuntu，它有一個很好的整合了ubuntu桌面系統和其他通知欄的客户端。Box，官方的Box.net也可以通過WebDav協議支持linux。</p><p>這裏有一段來自Canonical公司關於Ubuntu One的摘錄：</p><blockquote><p>從4月2日開始，就不能訪問Ubuntu One中的存儲或音樂了。Ubuntu One服務也不會再包含在Ubuntu 14.04 LTS中，而Ubuntu One的應用也將從Ubuntu、Google和Apple的應用商店移除。</p></blockquote><p>也就是説我們在ubuntu中失去了這項有用的服務。另一方面，把你的數據移動到一個更穩定、更好信譽的網盤提供商是一個比較好的選擇。</p><p>這裏簡要的説明一下怎樣在ubuntu中運行DropBox或者Box雲服務。</p><p>###在ubuntu中安裝DropBox雲盤</p><p>關於這個話題我們已經寫了很多，為了在ubuntu中安裝DropBox雲盤，你需要按照以下步驟去做，這裏提供了一個在ubuntu中一步步安裝和使用DropBox的步驟。</p><p>查看完整步驟，點這裏，或者下面的鏈接：</p>',10)),p("p",null,[u(e,{href:"http://www.liberiangeek.net/2013/03/how-to-install-dropbox-in-ubuntu-13-04-raring-ringtail/"},{default:n(()=>[...t[0]||(t[0]=[o("http://www.liberiangeek.net/2013/03/how-to-install-dropbox-in-ubuntu-13-04-raring-ringtail/",-1)])]),_:1})]),t[13]||(t[13]=r(`<p>###在Ubuntu中使用Box網盤</p><p>自從Box不再提供給包括ubuntu在內的linux一個全功能客户端，你就必須使用WebDav協議來訪問和存儲你賬户的東西。</p><p>按Ctrl – Alt – T來打開終端，終端被打開後，執行下面的命令來安裝包：</p><pre><code>sudo apt-get install davfs2
</code></pre><p>接下來，執行下面的命令來配置davfs2，選擇Yes來允許沒有權限的用户來掛載WebDav資源。</p><pre><code>sudo dpkg-reconfigure davfs2
</code></pre><p>接下來通過執行下面的命令把davfs2目錄複製到你的home目錄：</p><pre><code>sudo cp -r /etc/davfs2/ $HOME/.davfs2
</code></pre><p>然後執行下面命令獲取文件夾的所有權：</p><pre><code>sudo chown -R username $HOME/.davfs2/
</code></pre><p>用你的用户名代替username</p><p>接下來打開密碼文件輸入你的登錄憑證：</p><pre><code>gedit ~/.davfs2/secrets
</code></pre><p>然後鍵入你的用户名（email地址）和密碼，在文件末尾添加下面的行並保存。</p><pre><code>https://dav.box.com/dav richard@liberiangeek.net  &lt;box_password&gt;
</code></pre><p>用你的賬户信息替換上面的email地址和password。</p><p>接下來用下面的命令添加你的賬户到davfs2組中：</p><pre><code>sudo adduser &lt;username&gt; davfs2
</code></pre><p>然後用sudo gedit /etc/fstab 打開/etc/fstab在後面添加下面一行並保存：</p><pre><code>https://dav.box.com/dav/ /home/&lt;username&gt;/box  davfs _netdev,rw,user 0 0 
</code></pre><p>最後創建一個掛載點並掛載Box</p><pre><code>mkdir ~/box
</code></pre><p>重啓你的電腦，Box能開機自動掛載了，</p><p>享受下吧！</p><hr>`,25)),p("p",null,[t[2]||(t[2]=o("via: ",-1)),u(e,{href:"http://www.liberiangeek.net/2014/04/daily-ubuntu-tips-ubuntu-one-shuts-down-switch-to-dropbox-or-box-cloud-services/"},{default:n(()=>[...t[1]||(t[1]=[o("http://www.liberiangeek.net/2014/04/daily-ubuntu-tips-ubuntu-one-shuts-down-switch-to-dropbox-or-box-cloud-services/",-1)])]),_:1})]),p("p",null,[t[5]||(t[5]=o("譯者：",-1)),u(e,{href:"https://github.com/yujianxuechuan"},{default:n(()=>[...t[3]||(t[3]=[o("yujianxuechuan ",-1)])]),_:1}),t[6]||(t[6]=o(" 校對：",-1)),u(e,{href:"https://github.com/%E6%A0%A1wxy"},{default:n(()=>[...t[4]||(t[4]=[o("wxy",-1)])]),_:1})]),p("p",null,[t[9]||(t[9]=o("本文由 ",-1)),u(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[7]||(t[7]=[o("LCTT",-1)])]),_:1}),t[10]||(t[10]=o(" 原創翻譯，",-1)),u(e,{href:"http://linux.cn/"},{default:n(()=>[...t[8]||(t[8]=[o("Linux中國",-1)])]),_:1}),t[11]||(t[11]=o(" 榮譽推出",-1))])])}const v=s(i,[["render",l]]);export{_ as __pageData,v as default};
